import React, { useState } from 'react'


//Part of the DOM where user inputs a new task
const TaskInput = ({ addTodo }) => {
  const [inputFieldValue, setInputFieldValue] = useState("")

  return (
    <div>
        <input className='inputFieldBox' type="text" value={inputFieldValue} onChange={(eventObj) => setInputFieldValue(eventObj.target.value)} placeholder='Eneter a new task' />
        <button type="Submit">></button>
    </div>
  )
}

export default TaskInput
